recap:
O **`return`** entrega o prato pronto para quem chamou, e a chamada vira esse valor. O `console.log` só mostra a foto do prato. Sem `return`, a função devolve `undefined`.

```javascript
function dobro(n) {
  return n * 2;
}

const total = dobro(4);
console.log(total); // 8
```

exercises.solution:
function calcularTroco(pago, preco) {
  return pago - preco;
}

const primeiroTroco = calcularTroco(20, 15);
const segundoTroco = calcularTroco(50, 32);

console.log(`Troco: R$ ${primeiroTroco}`);
console.log(`Troco: R$ ${segundoTroco}`);

function caloriasDoTreino(minutos, porMinuto) {
  return minutos * porMinuto;
}

const segunda = caloriasDoTreino(30, 8);
const quarta = caloriasDoTreino(45, 6);

console.log(`Segunda: ${segunda} calorias`);
console.log(`Quarta: ${quarta} calorias`);
console.log(`Semana: ${segunda + quarta} calorias`);

function megasUsados(minutos, megasPorMinuto) {
  return minutos * megasPorMinuto;
}

function emGigas(megas) {
  return megas / 1000;
}

const filme = megasUsados(90, 25);
const serie = megasUsados(45, 20);

console.log(`Filme: ${emGigas(filme).toFixed(2)} GB`);
console.log(`Série: ${emGigas(serie).toFixed(2)} GB`);
console.log(`Total: ${emGigas(filme + serie).toFixed(2)} GB`);

